EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline, locality-aware covariance kernel.
# - data is stored in row-major order as DATA_TYPE[n, m]
# - We compute:
#     1) per-column means
#     2) center the data matrix
#     3) cov = (data^T * data) / (float_n - 1)
#
# The main differences from the naive PolyBench kernel are:
#   * Mean computation is reorganized to traverse data row-major.
#   * Covariance is computed as a full Gram matrix data^T * data with
#     k (row) outermost and j (column) innermost, improving memory locality.
@proc
def kernel_covariance_base(
    m: size,
    n: size,
    float_n: DATA_TYPE,
    data: DATA_TYPE[n, m] @ DRAM,
    cov: DATA_TYPE[m, m] @ DRAM,
    mean: DATA_TYPE[m] @ DRAM,
):
    assert n > 0
    assert m > 0

    # ------------------------------------------------------------------
    # 1. Compute per-column means in a row-major friendly way
    # ------------------------------------------------------------------

    # 1.a Zero out the mean vector
    for j in seq(0, m):
        mean[j] = 0.0

    # 1.b Accumulate column sums
    # Iterate over rows outermost and columns innermost so that
    # data[i, j] is accessed with j as the fast-moving index.
    for i in seq(0, n):
        for j in seq(0, m):
            mean[j] += data[i, j]

    # 1.c Normalize by the number of observations
    for j in seq(0, m):
        mean[j] = mean[j] / float_n

    # ------------------------------------------------------------------
    # 2. Center the data matrix: data[i, j] -= mean[j]
    # ------------------------------------------------------------------
    # Again, traverse rows first and columns innermost for row-major access.
    for i_cen in seq(0, n):
        for j_cen in seq(0, m):
            data[i_cen, j_cen] = data[i_cen, j_cen] - mean[j_cen]

    # ------------------------------------------------------------------
    # 3. Covariance computation via Gram matrix data^T * data
    # ------------------------------------------------------------------

    # 3.a Initialize covariance matrix to zero
    for i_init in seq(0, m):
        for j_init in seq(0, m):
            cov[i_init, j_init] = 0.0

    # 3.b Accumulate the Gram matrix:
    #       cov[i, j] += sum_k data[k, i] * data[k, j]
    # This computes the full symmetric covariance matrix. The order of
    # accumulation differs from the original PolyBench code but the
    # mathematical result is the same (up to FP round-off).
    for k_acc in seq(0, n):
        for i_acc in seq(0, m):
            for j_acc in seq(0, m):
                cov[i_acc, j_acc] += data[k_acc, i_acc] * data[k_acc, j_acc]

    # 3.c Scale by (n - 1) to obtain the unbiased covariance estimate
    for i_scale in seq(0, m):
        for j_scale in seq(0, m):
            cov[i_scale, j_scale] = cov[i_scale, j_scale] / (float_n - 1.0)

# ----------------------------------------------------------------------
# Scheduling / optimization.
# We keep the function signature expected by the C driver but apply
# locality and parallelism optimizations through Exo’s scheduling API.
# ----------------------------------------------------------------------

# Compile-time tunable tile sizes used by the scheduler (not extra
# kernel arguments). These can be adjusted for a particular cache
# hierarchy if desired.
TI = 32  # tile size along the feature dimension i_acc
TJ = 32  # tile size along the feature dimension j_acc

kernel_covariance_sched = kernel_covariance_base

# Parallelize loops that are provably independent across iterations.
# These loops:
#   * center different rows (i_cen)
#   * zero out different rows of cov (i_init)
#   * scale different rows of cov (i_scale)
# are all embarrassingly parallel.
kernel_covariance_sched = parallelize_loop(kernel_covariance_sched, "i_cen")
kernel_covariance_sched = parallelize_loop(kernel_covariance_sched, "i_init")
kernel_covariance_sched = parallelize_loop(kernel_covariance_sched, "i_scale")

# Tile the inner covariance accumulation over i_acc and j_acc to improve
# cache reuse of cov and the centered data. We use guarded tiles so the
# code remains correct for arbitrary m.
kernel_covariance_sched = divide_loop(
    kernel_covariance_sched, "i_acc", TI, ["io", "ii"], tail="guard"
)
kernel_covariance_sched = divide_loop(
    kernel_covariance_sched, "j_acc", TJ, ["jo", "jj"], tail="guard"
)

# Simplify expressions and clean up the IR after transformations.
kernel_covariance_sched = simplify(kernel_covariance_sched)

# Finally, rename to the externally visible kernel name expected by the
# C driver and PolyBench harness.
kernel_covariance = rename(kernel_covariance_sched, "kernel_covariance")
EXO END
